from codx.junior.engine.progress_callback import ProgressCallback, ProgressEventType

class KnowledgeLoader:
    def __init__(self, settings: CODXJuniorSettings, callback: Optional[ProgressCallback] = None):
        self.settings = settings
        self.callback = callback
        # ... existing init code ...

    async def load_with_progress(
        self,
        path: Optional[str] = None,
        last_update: Optional[float] = None,
        current_sources: Optional[Dict] = None,
        ignore_paths: Optional[List[str]] = None,
    ) -> List[Document]:
        """
        Load documents from filesystem with progress callback support.

        Args:
            path: Specific path to load (optional).
            last_update: Only load files modified after this timestamp.
            current_sources: Currently indexed sources.
            ignore_paths: Paths to ignore.

        Yields progress events via callback if provided.

        Returns:
            List of loaded documents.
        """
        documents = []
        files_to_load = self.list_repository_files(
            current_sources=current_sources,
            ignore_paths=ignore_paths,
            path=path,
        )

        if self.callback:
            await self.callback.on_progress(
                ProgressEventType.STARTED,
                {
                    "total_files": len(files_to_load),
                    "path": path,
                    "incremental": last_update is not None,
                }
            )

        for idx, file_path in enumerate(files_to_load):
            try:
                # Skip if not modified since last_update
                if last_update:
                    file_mtime = os.path.getmtime(file_path)
                    if file_mtime < last_update:
                        continue

                # Load the file
                doc = self._load_single_file(file_path)
                if doc:
                    documents.append(doc)

                    if self.callback:
                        await self.callback.on_progress(
                            ProgressEventType.DOCUMENT_PROCESSING,
                            {
                                "file_index": idx,
                                "total_files": len(files_to_load),
                                "source": file_path,
                                "content_length": len(doc.page_content),
                            }
                        )
            except Exception as ex:
                if self.callback:
                    await self.callback.on_error(ex, {"source": file_path})
                else:
                    logger.exception(f"Error loading {file_path}")

        if self.callback:
            await self.callback.on_progress(
                ProgressEventType.BATCH_COMPLETE,
                {
                    "documents_loaded": len(documents),
                    "files_processed": len(files_to_load),
                }
            )

        return documents

from codx.junior.engine.progress_callback import ProgressCallback, ProgressEventType

class Knowledge:
    def __init__(self, settings: CODXJuniorSettings, callback: Optional[ProgressCallback] = None):
        # ... existing init ...
        self.callback = callback

    async def parallel_enrich(self, documents, metadata):
        """
        Enrich documents in parallel with progress reporting.

        Args:
            documents: Documents to enrich.
            metadata: Shared metadata to add.

        Yields progress events via callback.

        Returns:
            List of enriched documents.
        """
        from concurrent.futures import ThreadPoolExecutor, as_completed
        import asyncio

        valid_documents = []
        total = len(documents)
        completed = 0

        if self.callback:
            await self.callback.on_progress(
                ProgressEventType.DOCUMENT_PROCESSING,
                {
                    "stage": "enrichment",
                    "total_documents": total,
                    "message": f"Starting enrichment of {total} documents",
                }
            )

        with ThreadPoolExecutor(max_workers=4) as executor:
            futures = {
                executor.submit(
                    self.enrich_document,
                    doc=doc,
                    metadata=metadata,
                    categories=self.get_categories()
                ): idx for idx, doc in enumerate(documents)
            }

            for future in as_completed(futures):
                idx = futures[future]
                try:
                    result = future.result()
                    if result is not None:
                        valid_documents.append(result)

                    completed += 1

                    if self.callback:
                        await self.callback.on_progress(
                            ProgressEventType.DOCUMENT_ENRICHED,
                            {
                                "index": idx,
                                "total": total,
                                "completed": completed,
                                "progress_percent": int((completed / total) * 100),
                                "source": result.metadata.get("source") if result else "unknown",
                            }
                        )
                except Exception as ex:
                    if self.callback:
                        await self.callback.on_error(
                            ex,
                            {
                                "document_index": idx,
                                "stage": "enrichment",
                                "total_documents": total,
                            }
                        )

        if self.callback:
            await self.callback.on_progress(
                ProgressEventType.ITERATION_COMPLETE,
                {
                    "stage": "enrichment",
                    "documents_enriched": len(valid_documents),
                    "documents_failed": total - len(valid_documents),
                }
            )

        return valid_documents

    async def index_documents(self, documents, raiseIfError=False, callback: Optional[ProgressCallback] = None):
        """
        Index documents with progress callback support.

        Args:
            documents: Documents to index.
            raiseIfError: Raise on first error.
            callback: Progress callback.

        Yields progress events.
        """
        _callback = callback or self.callback

        index_date = datetime.now().strftime("%m/%d/%YT%H:%M:%S")
        all_sources = list(set([doc.metadata["source"] for doc in documents]))
        all_sources_with_md5 = dict(
            [(source, calculate_md5(source)) for source in all_sources]
        )

        if _callback:
            await _callback.on_progress(
                ProgressEventType.DOCUMENT_PROCESSING,
                {
                    "stage": "enrichment",
                    "total_documents": len(documents),
                    "unique_sources": len(all_sources),
                }
            )

        metadata = {"index_date": index_date}
        enriched_documents = await self.parallel_enrich(
            documents=documents,
            metadata=metadata,
        )

        # Delete old versions
        self.delete_documents(enriched_documents)

        if _callback:
            await _callback.on_progress(
                ProgressEventType.DOCUMENT_PROCESSING,
                {
                    "stage": "indexing",
                    "total_documents": len(enriched_documents),
                }
            )

        indexed_count = 0
        failed_count = 0

        for doc in enriched_documents:
            source = doc.metadata.get("source")
            try:
                doc.metadata["index_date"] = index_date
                doc.metadata["file_md5"] = all_sources_with_md5.get(source, "")

                self.get_db().index_documents(documents=[doc])
                indexed_count += 1

                if _callback:
                    await _callback.on_progress(
                        ProgressEventType.DOCUMENT_INDEXED,
                        {
                            "source": source,
                            "indexed_count": indexed_count,
                            "total": len(enriched_documents),
                            "progress_percent": int((indexed_count / len(enriched_documents)) * 100),
                        }
                    )

            except Exception as ex:
                failed_count += 1

                if _callback:
                    await _callback.on_error(
                        ex,
                        {
                            "source": source,
                            "stage": "indexing",
                            "indexed_so_far": indexed_count,
                        }
                    )

                if "float data" in str(ex):
                    logger.error(f"Float data error, resetting index for {self.settings.abs_project_path}")
                    self.reset()
                elif raiseIfError:
                    raise ex

        # Update project summary
        try:
            if _callback:
                await _callback.on_progress(
                    ProgressEventType.DOCUMENT_PROCESSING,
                    {
                        "stage": "summary_generation",
                        "message": "Generating project summary...",
                    }
                )

            self.build_project_summary(added_sources=all_sources)
        except Exception as ex:
            logger.exception("Error updating project summary: %s", ex)
            if _callback:
                await _callback.on_error(ex, {"stage": "summary_generation"})

        if _callback:
            await _callback.on_progress(
                ProgressEventType.COMPLETED,
                {
                    "indexed_count": indexed_count,
                    "failed_count": failed_count,
                    "total": len(enriched_documents),
                }
            )

// Listen for all index progress events
const subscribeToIndexProgress = (socket) => {
  // Started event
  socket.on('codx-junior-index-progress-started', (data) => {
    console.log(`📦 Indexing started: ${data.total_files} files`);
    updateUI({
      status: 'indexing',
      progress: 0,
      message: data.message,
    });
  });

  // Document processing events
  socket.on('codx-junior-index-progress-document-processing', (data) => {
    console.log(`📄 Processing: ${data.source}`);
    updateUI({
      status: 'processing',
      progress: Math.round((data.file_index / data.total_files) * 100),
      current_file: data.source,
      stage: 'Loading documents',
    });
  });

  // Document enriched events
  socket.on('codx-junior-index-progress-document-enriched', (data) => {
    console.log(`✨ Enriched: ${data.source} (${data.progress_percent}%)`);
    updateUI({
      status: 'enriching',
      progress: data.progress_percent,
      completed: data.completed,
      total: data.total,
      stage: 'Enriching documents with AI',
    });
  });

  // Document indexed events
  socket.on('codx-junior-index-progress-document-indexed', (data) => {
    console.log(`📚 Indexed: ${data.source} (${data.progress_percent}%)`);
    updateUI({
      status: 'indexing_db',
      progress: data.progress_percent,
      indexed_count: data.indexed_count,
      total: data.total,
      stage: 'Writing to database',
    });
  });

  // Batch complete
  socket.on('codx-junior-index-progress-batch-complete', (data) => {
    console.log(`✅ Batch complete: ${data.documents_loaded} documents`);
  });

  // Completion event
  socket.on('codx-junior-index-progress-completed', (data) => {
    console.log(`🎉 Indexing complete: ${data.indexed_count}/${data.total}`);
    updateUI({
      status: 'complete',
      progress: 100,
      message: `Successfully indexed ${data.indexed_count} documents`,
    });
  });

  // Error event
  socket.on('codx-junior-index-error', (data) => {
    console.error(`❌ Error: ${data.error_type} - ${data.message}`);
    updateUI({
      status: 'error',
      error: data.message,
      context: data.context,
    });
  });
};

const updateUI = (state) => {
  // Update progress bar, status message, etc.
  document.getElementById('progress-bar').style.width = `${state.progress}%`;
  document.getElementById('status-message').textContent = state.message;
  document.getElementById('current-stage').textContent = state.stage;
};
